DROP TABLE IF EXISTS `sakip_sumber_kinerja_v`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `sakip_sumber_kinerja_v`  AS SELECT concat('sasaran_renstra:',`s`.`id`) AS `value_key`, `s`.`id` AS `sumber_id`, 'sasaran_renstra' AS `sumber_ref`, `r`.`kd_wilayah` AS `kd_wilayah`, `r`.`kd_opd` AS `kd_opd`, concat('Sasaran — ',`s`.`kode_sasaran`,' ',`s`.`nama_sasaran`) AS `uraian` FROM (((`sasaran_renstra_neo` `s` join `tujuan_renstra_neo` `t` on(`t`.`id` = `s`.`tujuan_id` and `t`.`is_deleted` = 0)) join `misi_renstra_neo` `m` on(`m`.`id` = `t`.`misi_id` and `m`.`is_deleted` = 0)) join `renstra_neo` `r` on(`r`.`id` = `m`.`renstra_id` and `r`.`is_deleted` = 0)) WHERE `s`.`is_deleted` = 0union allselect concat('program_renstra:',`p`.`id`) AS `CONCAT('program_renstra:',p.id)`,`p`.`id` AS `id`,'program_renstra' AS `program_renstra`,`r`.`kd_wilayah` AS `kd_wilayah`,`r`.`kd_opd` AS `kd_opd`,concat('Program — ',`p`.`kode_program`,' ',`p`.`uraian`) AS `CONCAT('Program — ',p.kode_program,' ',p.uraian)` from ((((`program_renstra_neo` `p` join `sasaran_renstra_neo` `s` on(`s`.`id` = `p`.`sasaran_id` and `s`.`is_deleted` = 0)) join `tujuan_renstra_neo` `t` on(`t`.`id` = `s`.`tujuan_id` and `t`.`is_deleted` = 0)) join `misi_renstra_neo` `m` on(`m`.`id` = `t`.`misi_id` and `m`.`is_deleted` = 0)) join `renstra_neo` `r` on(`r`.`id` = `m`.`renstra_id` and `r`.`is_deleted` = 0)) where `p`.`is_deleted` = 0 union all select concat('kegiatan_renstra:',`k`.`id`) AS `CONCAT('kegiatan_renstra:',k.id)`,`k`.`id` AS `id`,'kegiatan_renstra' AS `kegiatan_renstra`,`r`.`kd_wilayah` AS `kd_wilayah`,`r`.`kd_opd` AS `kd_opd`,concat('Kegiatan — ',`k`.`kode_kegiatan`,' ',`k`.`uraian`) AS `CONCAT('Kegiatan — ',k.kode_kegiatan,' ',k.uraian)` from (((((`kegiatan_renstra_neo` `k` join `program_renstra_neo` `p` on(`p`.`id` = `k`.`program_id` and `p`.`is_deleted` = 0)) join `sasaran_renstra_neo` `s` on(`s`.`id` = `p`.`sasaran_id` and `s`.`is_deleted` = 0)) join `tujuan_renstra_neo` `t` on(`t`.`id` = `s`.`tujuan_id` and `t`.`is_deleted` = 0)) join `misi_renstra_neo` `m` on(`m`.`id` = `t`.`misi_id` and `m`.`is_deleted` = 0)) join `renstra_neo` `r` on(`r`.`id` = `m`.`renstra_id` and `r`.`is_deleted` = 0)) where `k`.`is_deleted` = 0 union all select concat('sub_kegiatan_renstra:',`sk`.`id`) AS `CONCAT('sub_kegiatan_renstra:',sk.id)`,`sk`.`id` AS `id`,'sub_kegiatan_renstra' AS `sub_kegiatan_renstra`,`r`.`kd_wilayah` AS `kd_wilayah`,`r`.`kd_opd` AS `kd_opd`,concat('Sub Kegiatan — ',`rk`.`kode`,' ',`rk`.`uraian`) AS `CONCAT('Sub Kegiatan — ',rk.kode,' ',rk.uraian)` from (((((((`sub_kegiatan_renstra_neo` `sk` join `rekening_kegiatan` `rk` on(`rk`.`id` = `sk`.`master_sub_kegiatan_id`)) join `kegiatan_renstra_neo` `k` on(`k`.`id` = `sk`.`kegiatan_renstra_id` and `k`.`is_deleted` = 0)) join `program_renstra_neo` `p` on(`p`.`id` = `k`.`program_id` and `p`.`is_deleted` = 0)) join `sasaran_renstra_neo` `s` on(`s`.`id` = `p`.`sasaran_id` and `s`.`is_deleted` = 0)) join `tujuan_renstra_neo` `t` on(`t`.`id` = `s`.`tujuan_id` and `t`.`is_deleted` = 0)) join `misi_renstra_neo` `m` on(`m`.`id` = `t`.`misi_id` and `m`.`is_deleted` = 0)) join `renstra_neo` `r` on(`r`.`id` = `m`.`renstra_id` and `r`.`is_deleted` = 0)) where `sk`.`is_deleted` = 0  ;

