INSERT INTO `ref_template_naskah` (`id`, `jenis_id`, `nama_template`, `form_schema`, `kd_wilayah`, `kd_opd`, `username_insert`, `tgl_insert`, `username_update`, `tgl_update`, `keterangan`) VALUES
(1, 5, 'Template Penetapan', '[\n  {\n    \"type\": \"message\",\n    \"variant\": \"positive\",\n    \"label\": \"Perhatian\",\n    \"list\": [\n      \"jika mengedit data dan merubah Nomor Surat maka akan dianggap tambah data baru\",\n      \"simpan terlebih dahulu sebelum cetak dokumen\"\n    ]\n  },\n\n  {\n    \"type\": \"group\",\n    \"columns\": 3,\n    \"fields\": [\n      {\n        \"type\": \"auto_nomor\",\n        \"label\": \"Nomor Surat\",\n        \"name\": \"nomor\",\n        \"required\": true\n      },\n      {\n        \"type\": \"date\",\n        \"label\": \"Tanggal Surat\",\n        \"name\": \"tgl_surat_dibuat\",\n        \"required\": true\n      },\n      {\n        \"type\": \"file\",\n        \"label\": \"Pilih File Dokumen\",\n        \"name\": \"file\"\n      }\n    ]\n  },\n\n  {\n    \"type\": \"textarea\",\n    \"label\": \"Tentang\",\n    \"name\": \"tentang\",\n    \"required\": true\n  },\n\n  {\n    \"type\": \"group\",\n    \"columns\": 3,\n    \"fields\": [\n      {\n        \"type\": \"dropdown_ajax\",\n        \"label\": \"Pemberi Tugas\",\n        \"name\": \"pemberi_tgs\",\n        \"source\": \"pemberi_tgs\",\n        \"required\": true\n      },\n      {\n        \"type\": \"text\",\n        \"label\": \"Jabatan Pemberi Tugas\",\n        \"name\": \"jbt_pemberi_tgs\",\n        \"required\": true\n      },\n      {\n        \"type\": \"text\",\n        \"label\": \"Pangkat Pemberi Tugas\",\n        \"name\": \"pangkat_pemberi_tgs\",\n        \"required\": true\n      }\n    ]\n  },\n\n  {\n    \"type\": \"section\",\n    \"label\": \"Menimbang\",\n    \"name\": \"menimbang\",\n    \"section_type\": \"list_huruf\"\n  },\n\n  {\n    \"type\": \"section\",\n    \"label\": \"Mengingat\",\n    \"name\": \"mengingat\",\n    \"section_type\": \"list_nomor\"\n  },\n\n  {\n    \"type\": \"section\",\n    \"label\": \"Menetapkan\",\n    \"name\": \"menetapkan\",\n    \"section_type\": \"list_keputusan\"\n  },\n\n  {\n    \"type\": \"dropdown_ajax\",\n    \"label\": \"Nama ASN ditugaskan\",\n    \"name\": \"asn\",\n    \"source\": \"asn\"\n  },\n\n  {\n    \"type\": \"table\",\n    \"name\": \"nama_ditugaskan\",\n    \"columns\": [\n      \"nama\",\n      \"pangkat\",\n      \"nip\",\n      \"jabatan\",\n      \"jabatan_sk\"\n    ]\n  },\n\n  {\n    \"type\": \"toggle\",\n    \"label\": \"Lampiran SK bentuk Tabel\",\n    \"name\": \"bentuk_lampiran\"\n  },\n\n  {\n    \"type\": \"section\",\n    \"label\": \"Tembusan\",\n    \"name\": \"tembusan\",\n    \"section_type\": \"list_nomor\"\n  },\n\n  {\n    \"type\": \"textarea\",\n    \"label\": \"Keterangan\",\n    \"name\": \"keterangan\"\n  },\n\n  {\n    \"type\": \"toggle\",\n    \"label\": \"Non Aktif\",\n    \"name\": \"disable\"\n  }\n]', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
