(29, '2021', '76.01', '1.03.0.00.0.00.01.0000', '15 TAHUN 2021', '2021-01-05', 'pengangkatan Pengantar/administrasi surat-menyurat dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2021', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"111111111111111115\", \"nama\": \"Nurafni Rusdin, SE\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"Pengantar/Administrasi Surat-Menyurat\"}, \"1\": {\"nip\": \"111111111111111113\", \"nama\": \"Sudirman\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"Pengantar/Administrasi Surat-Menyurat\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk kelancaran pelaksanaan administrasi dokumen persuratan yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pengantar Surat pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Menerima dan mempelajari surat;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Menyortir surat menurut jenis dan sifatnya;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Mencatat dan mengendalikan surat;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Mengantar dan memberi lembar pengantar surat/ekspedisi;\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"Mendokumentasikan surat;\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"Melaporkan hasil pelaksanaan tugas secara tertulis dan lisan kepada atasan sesuai prosedur yang berlaku;\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulia maupun lisan.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(31, '0000', '76.01', '1.03.0.00.0.00.01.0000', '12 TAHUN 2021', '2021-01-05', 'pengangkatan administrasi kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2021', '197508022006041011', 'kepala dinas', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"111111111111111116\", \"nama\": \"Asrafil\", \"jabatan\": \"honorer\", \"pangkat\": \"Juru , I/-\", \"jabatan_sk\": \"\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk kelancaran pelaksanaan administrasi perkantoran yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pengantar Surat pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 33 Tahun 2019 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 10 Tahun 2019 tanggal 30 Desember 2019 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2020;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 47 Tahun 2018 tanggal 30 Desember 2019 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2020.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Penetapan adalah sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"Mencatat, memeriksa dan memastikan Agenda Kantor Kepala OPD;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"Melakukan Entri Data Perkantoran Kepala OPD;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"Melaporkan hasil pelaksanaan tugas secara tertulis dan lisan kepada atasan sesuai prosedur yang berlaku;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulia maupun lisan.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2020.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(32, '0000', '76.01', '1.03.0.00.0.00.01.0000', '17 TAHUN 2021', '2021-01-05', 'pengangkatan pejabat pembantu pengurus barang pengguna dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2021', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\": {\"nip\": \"198510092014091002\", \"nama\": \"Agussalim T\", \"jabatan\": \"STAF\", \"pangkat\": \"Pengatur Muda, II/a\", \"jabatan_sk\": \"Pembantu Pengurus Barang Pengguna\"}}', 0, '{\"0\": {\"isi\": \"bahwa untuk pelaksanaan proses kerja pengelolaan asset dan barang, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Paasangkayu, maka dipandang perlu mengangkat pembantu pengurus ÃÂ barang pengguna pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2021;\"}, \"1\": {\"isi\": \"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"}, \"2\": {\"isi\": \"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\": {\"isi\": \"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"}, \"1\": {\"isi\": \"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"}, \"2\": {\"isi\": \"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"}, \"3\": {\"isi\": \"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"}, \"4\": {\"isi\": \"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"}, \"5\": {\"isi\": \"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"}, \"6\": {\"isi\": \"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"}, \"7\": {\"isi\": \"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang/Jasa Pemerintah;\"}, \"8\": {\"isi\": \"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\"}, \"9\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"}, \"10\": {\"isi\": \"Peraturan Menteri Dalam Negeri Nomor 64 Tahun 2020 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2021\"}, \"11\": {\"isi\": \"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"}, \"12\": {\"isi\": \"Peraturan Daerah Kabupaten Pasangkayu Nomor 9 Tahun 2020 tanggal 29 Desember 2020 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2021;\"}, \"13\": {\"isi\": \"Peraturan Bupati Kabupaten Pasangkayu Nomor 28 Tahun 2020 tanggal 29 Desember 2020 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2021.\"}}', '{\"0\": {\"isi\": \"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\", \"p_l\": \"P\"}, \"1\": {\"isi\": \"membantu menyiapkan dokumen rencana kebutuhan dan penganggaran barang milik daerah;\", \"p_l\": \"L\"}, \"2\": {\"isi\": \"menyiapkan usulan permohonan penetapan status penggunaan barang milik daerah yang diperoleh dari beban APBD dan perolehan lainnya yang sah;\", \"p_l\": \"L\"}, \"3\": {\"isi\": \"melaksanakan pencatatan dan inventarisasi barang milik daerah;\", \"p_l\": \"L\"}, \"4\": {\"isi\": \"membantu mengamankan barang milik daerah yang berada pada Pengguna Barang;\", \"p_l\": \"L\"}, \"5\": {\"isi\": \"menyiapkan dokumen pengajuan usulan pemanfaatan dan pemindahtanganan barang milik daerah berupa tanah dan/atau bangunan yang tidak memerlukan persetujuan DPRD dan barang milik daerah selain tanah dan/atau bangunan;\", \"p_l\": \"L\"}, \"6\": {\"isi\": \"menyiapkan dokumen penyerahan barang milik daerah berupa tanah dan/atau bangunan yang tidak digunakan untuk kepentingan penyelenggaraan tugas dan fungsi Pengguna Barang dan sedang tidak dimanfaatkan pihak lain;\", \"p_l\": \"L\"}, \"7\": {\"isi\": \"menyiapkan dokumen pengajuan usulan pemusnahan dan penghapusan barang milik daerah;\", \"p_l\": \"L\"}, \"8\": {\"isi\": \"menyusun laporan barang semesteran dan tahunan;\", \"p_l\": \"L\"}, \"9\": {\"isi\": \"menyiapkan Surat Permintaan Barang (SPB) berdasarkan nota permintaan barang;\", \"p_l\": \"L\"}, \"10\": {\"isi\": \"mengajukan Surat Permintaan Barang (SPB) kepada Pejabat Penatausahaan Barang Pengguna;\", \"p_l\": \"L\"}, \"11\": {\"isi\": \"menyerahkan barang berdasarkan Surat Perintah Penyaluran Barang (SPPB) yang dituangkan dalam berita acara penyerahan barang;\", \"p_l\": \"L\"}, \"12\": {\"isi\": \"membuat Kartu Inventaris Ruangan (KIR) semesteran dan tahunan;\", \"p_l\": \"L\"}, \"13\": {\"isi\": \"memberi label barang milik daerah;\", \"p_l\": \"L\"}, \"14\": {\"isi\": \"mengajukan permohonan persetujuan kepada Pejabat Penatausahaan Pengguna Barang atas perubahan kondisi fisik barang milik daerah berdasarkan pengecekan fisik barang;\", \"p_l\": \"L\"}, \"15\": {\"isi\": \"melakukan stock opname barang persediaan;\", \"p_l\": \"L\"}, \"16\": {\"isi\": \"menyimpan dokumen, antara lain: fotokopi/salinan dokumen kepemilikan barang milik daerah dan menyimpan asli/fotokopi/salinan dokumen penatausahaan;\", \"p_l\": \"L\"}, \"17\": {\"isi\": \"melakukan rekonsiliasi dalam rangka penyusunan laporan barang Pengguna Barang dan laporan barang milik daerah;\", \"p_l\": \"L\"}, \"18\": {\"isi\": \"membuat laporan mutasi barang setiap bulan yang disampaikan kepada Pengelola Barang melalui Pengguna Barang setelah diteliti oleh Pejabat Penatausahaan Pengguna Barang.\", \"p_l\": \"L\"}}', '{\"0\": {\"isi\": \"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2021.\", \"p_l\": \"P\"}}', '{\"0\": {\"isi\": \"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\", \"p_l\": \"P\"}}', '{}', '{\"0\": {\"tembusan\": \"Bupati                                            Pasangkayu, di Pasangkayu\"}, \"1\": {\"tembusan\": \"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"}, \"2\": {\"tembusan\": \"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"}, \"3\": {\"tembusan\": \"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"}, \"4\": {\"tembusan\": \"Masing-masing yang bersangkutan\"}, \"5\": {\"tembusan\": \"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
