(47, '0000', '76.01', '1.03.0.00.0.00.01.0000', '02 TAHUN 2022', '2022-01-03', 'Pengangkatan Pejabat Pembuat Komitmen (PPK)  Dinas Pekerjaan Umum Dan Penataan Ruang Kabupaten Pasangkayu Tahun 2022', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\":{\"nama\":\"Sumarlin, ST\",\"pangkat\":\"Pembina , IV/a\",\"nip\":\"198006152006041018\",\"jabatan\":\"Sekretaris Dinas\",\"jabatan_sk\":\"PPK Cipta Karya dan Sekretariat\"},\"1\":{\"nama\":\"Kamaruddin, ST\",\"pangkat\":\"Pembina , IV/a\",\"nip\":\"197308142005021003\",\"jabatan\":\"Kepala Bidang Pembinaan Jasa Konstruksi\",\"jabatan_sk\":\"PPK Pembinaan Jasa Konstruksi\"},\"2\":{\"nama\":\"Herry Hasanuddin. M, ST\",\"pangkat\":\"Penata Tingkat I, III/d\",\"nip\":\"197101152007011019\",\"jabatan\":\"Kepala Bidang Penataan Ruang\",\"jabatan_sk\":\"PPK Penataan Ruang\"},\"3\":{\"nama\":\"Pusmahasib, S.Si\",\"pangkat\":\"Penata , III/c\",\"nip\":\"197908252009031003\",\"jabatan\":\"Kepala Bidang Sumber Daya Air\",\"jabatan_sk\":\"PPK Sumber Daya Air\"},\"4\":{\"nama\":\"I Nyoman Sumerta, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198301012010011020\",\"jabatan\":\"Kepala Bidang Binamarga\",\"jabatan_sk\":\"PPK Binamarga\"}}', 0, '{\"0\":{\"isi\":\"Bahwa untuk pelaksanaan proses kerja pengadaan barang / jasa pemerintah yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pembuat Komitmen (PPK) pada Dinas Pekerjaan Umum Kabupaten Pasangkayu\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\"},\"7\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\"},\"8\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah;\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 27 Tahun 2021 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"13\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 7 Tahun 2021 tanggal 30 Desember 2021 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"14\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 34 Tahun 2021 tanggal 31 Desember 2021 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2022.\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"menyusun perencanaan pengadaan\",\"p_l\":\"L\"},\"2\":{\"isi\":\"menetapkan spesifikasi teknis/Kerangka Acuan Kerja (KAK)\",\"p_l\":\"L\"},\"3\":{\"isi\":\"menetapkan rancangan kontrak\",\"p_l\":\"L\"},\"4\":{\"isi\":\"menetapkan HPS\",\"p_l\":\"L\"},\"5\":{\"isi\":\"menetapkan besaran uang muka yang akan dibayarkan kepada Penyedia\",\"p_l\":\"L\"},\"6\":{\"isi\":\"mengusulkan perubahan jadwal kegiatan\",\"p_l\":\"L\"},\"7\":{\"isi\":\"menetapkan tim pendukung\",\"p_l\":\"L\"},\"8\":{\"isi\":\"menetapkan tim atau tenaga ahli\",\"p_l\":\"L\"},\"9\":{\"isi\":\"melaksanakan E-purchasing untuk nilai paling sedikit di atas Rp200.000.000,00 (dua ratus juta rupiah)\",\"p_l\":\"L\"},\"10\":{\"isi\":\"menetapkan Surat Penunjukan Penyedia Barang/Jasa\",\"p_l\":\"L\"},\"11\":{\"isi\":\"mengendalikan Kontrak\",\"p_l\":\"L\"},\"12\":{\"isi\":\"melaporkan pelaksanaan dan penyelesaian kegiatan kepada PA/KPA\",\"p_l\":\"L\"},\"13\":{\"isi\":\"menyerahkan hasil pekerjaan pelaksanaan kegiatan kepada PA/KPA dengan berita acara penyerahan\",\"p_l\":\"L\"},\"14\":{\"isi\":\"menyimpan dan menjaga keutuhan seluruh dokumen pelaksanaan kegiatan\",\"p_l\":\"L\"},\"15\":{\"isi\":\"menilai kinerja Penyedia\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Selain tugas pokok dan kewenangan sebagaimana dimaksud, dalam hal diperlukan, PPK,dapat\",\"p_l\":\"P\"},\"1\":{\"isi\":\"melakukan tindakan yang mengakibatkan pengeluaran anggaran belanja\",\"p_l\":\"L\"},\"2\":{\"isi\":\"mengadakan dan menetapkan perjanjian dengan pihak lain dalam batas anggaran belanja yang telah ditetapkan\",\"p_l\":\"L\"},\"3\":{\"isi\":\"PPK dalam melaksanakan tugas sebagaimana dimaksud dapat dibantu oleh Pengelola Pengadaan Barang/Jasa\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Melaporkan kemajuan pekerjaan termasuk penyerapan anggaran dan hambatan pelaksanaan pekerjaan kepada PA/KPA setiap triwulan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Menyimpan dan menjaga keutuhan seluruh dokumen pelaksanaan Pengadaan barang/Jasa Pemerintah\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2022.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(48, '0000', '76.01', '1.03.0.00.0.00.01.0000', '03 TAHUN 2022', '2022-01-03', 'pengangkatan pejabat penatausahaan keuangan  dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2022', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\":{\"nama\":\"Felix Datuan, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198407252009031001\",\"jabatan\":\"Kepala Sub Bagian Keuangan\",\"jabatan_sk\":\"Pejabat Penatausahaan Keuangan\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk menyediakan pengelolaan keuangan Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Penatausahaan Keuangan pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Nomor 4286);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Nomor 4355);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor125, Tambahan Lembaran Negara Nomor 4437) sebagimana telah diubah beberapa kali terakhir dengan Undang-undang Nomor 12 Tahun 2008 tentang Perubahan kedua atas undang-undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2008 Nomor 59, Tambahan Lembaran Negara Nomor 4844);\"},\"5\":{\"isi\":\"Peraturan Pemerintah Nomor 58 Tahun 2005 tentang Pengelolaan Keuangan Daerah (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 140, Tambahan Lembaran Negara Republik Indonesia Nomor 4578);\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 8 Tahun 2006 tentang Laporan Keuangan dan Kinerja Instansi Pemerintah (Lembaran Negara Republik Indonesia Tahun 2006 Nomor 25, Tambahan Lembaran Negara Republik Indonesia Nomor 4614);\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah;\"},\"9\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah;\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 7 Tahun 2021 tanggal 30 Desember 2021 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 34 Tahun 2021 tanggal 31 Desember 2021 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2022.\"}}', '{\"0\":{\"isi\":\"Meneliti Kelengkapan SPP-LS pengadaan barang dan jasa yang disampaikan oleh bendahara pengeluaran dan diketahui/disetujui oleh PPTK;\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Meneliti kelengkapan SPP-UP, SPP-GU dan SPP-LS gaji dan tunjangan PNS serta penghasilan lainnya yang ditetapkan sesuai dengan ketentuan perundang-undangan yang diajukan oleh bendahara pengeluaran;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Melakukan Verifikasi SPP;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Menyiapkan SPM;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Melakukan verifikasi harian atas penerimaan;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Melaksanakan akuntansi SKPD; dan\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Menyiapkan laporan keuangan SKPD.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada APBD Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2022.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu;\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu;\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu;\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu;\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan;\"},\"5\":{\"tembusan\":\"Pertinggal.\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(49, '0000', '76.01', '1.03.0.00.0.00.01.0000', '06 TAHUN 2022', '2022-01-03', 'pengangkatan pejabat pengadaan barang / jasa pemerintah pada dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2022', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\":{\"nama\":\"I Ketut Suriyana, ST\",\"pangkat\":\"Penata , III/c\",\"nip\":\"198404262011011011\",\"jabatan\":\"Teknik Penyehatan Lingkungan Ahli Muda\",\"jabatan_sk\":\"Pejabat Pengadaan Pekerjaan Konstruksi Bidang Cipta Karya\"},\"1\":{\"nama\":\"Alwi Mansyur, A.Md\",\"pangkat\":\"Penata Muda, III/b\",\"nip\":\"198007112006041010\",\"jabatan\":\"Staff\",\"jabatan_sk\":\"Pejabat Pengadaan Bidang Binamarga, Cipta Karya, Sumber Daya Air , Sekretariat dan Pembinaan Jasa Konstruksi dan Konsultansi\"},\"2\":{\"nama\":\"Ariyadi\",\"pangkat\":\"Pengatur , II/c\",\"nip\":\"197603042011011003\",\"jabatan\":\"Staff\",\"jabatan_sk\":\"Pejabat Pengadaan Pekerjaan Konstruksi Bidang Sumber Daya Air\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk pelaksanaan proses kerja pengelolaan Barang / Jasa yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pengadaan Barang / Jasa pada Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581)\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63)\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270)\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286)\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355)\"},\"5\":{\"isi\":\"Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 125, Tambahan Lembaran Negara Republik Indonesia Nomor 4437) sebagaimana telah diubah dengan Undang-Undang Nomor 8 Tahun 2005 tentang Penetapan Peraturan Pemerintah Pengganti Undang-Undang Nomor 3 Tahun 2005 tentang Perubahan Undang-Undang Nomor 32 Tahun 2004 tentang Pemerintahan Daerah menjadi Undang-Undang (Lembaran Negara Republik Indonesia Tahun 2005 Nomor 108, Tambahan Lembaran Negara Republik Indonesia Nomor 4548)\"},\"6\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438)\"},\"7\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi\"},\"8\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2018 tentang Pengadaan Barang/Jasa Pemerintah\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah sebagaimana telah diubah dengan Peraturan Menteri Dalam Negeri Nomor 59 Tahun 2007 tentang Perubahan Atas Peraturan Menteri Dalam Negeri Nomor 13 Tahun 2006 tentang Pedoman Pengelolaan Keuangan Daerah\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 27 Tahun 2021 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5)\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 35 Tahun 2016 tentang Pembentukan Organisasi Perangkat Daerah\"},\"13\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 7 Tahun 2021 tanggal 30 Desember 2021 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2022;\"},\"14\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 34 Tahun 2021 tanggal 31 Desember 2021 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2022.\"}}', '{\"0\":{\"isi\":\"Tugas Pejabat sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"melaksanakan persiapan dan pelaksanaan Pengadaan Langsung;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Barang/Pekerjaan Konstruksi/Jasa Lainnya yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"melaksanakan persiapan dan pelaksanaan Penunjukan Langsung untuk pengadaan Jasa Konsultansi yang bernilai paling banyak Rp100.000.000,00 (seratus juta rupiah);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"melaksanakan E-purchasing yang bernilai paling banyak Rp200.000.000,00 (dua ratus juta rupiah);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Menyerahkan dokumen asli pemilihan penyedia barang / jasa Pemerintah kepada pengguna anggaran;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Membuat laporan mengenai proses dan hasil pengadaan kepada pengguna anggaran; dan\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Memberikan pertanggungjawaban atas pelaksanaan kegiatan pengadaan barang / jasa Konstruksi kepada pengguna anggaran\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2022\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"tembusan\":\"Bupati                                            Pasangkayu, di Pasangkayu\"},\"1\":{\"tembusan\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\"},\"2\":{\"tembusan\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\"},\"3\":{\"tembusan\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\"},\"4\":{\"tembusan\":\"Masing-masing yang bersangkutan\"},\"5\":{\"tembusan\":\"Pertinggal\"}}', '', '', '0000-00-00 00:00:00', '', '0000-00-00 00:00:00', '', 0, 0),
(50, '0000', '76.01', '1.03.0.00.0.00.01.0000', '10 TAHUN 2022', '2022-01-03', 'penetapan administrator keuangan dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2022', '197508022006041011', 'kepala', 'Pembina Tingkat I, IV/b', 'Budiyansa, ST', '{\"0\":{\"nama\":\"Alwi Mansyur, A.Md\",\"pangkat\":\"Penata Muda Tingkat I, III/b\",\"nip\":\"198007112006041010\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Administrator Keuangan\"},\"1\":{\"nama\":\"Santi, SE\",\"pangkat\":\"Penata Muda Tingkat I, III/b\",\"nip\":\"198509192010012002\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Administrator Keuangan\"},\"2\":{\"nama\":\"Abdul Haris Rustam, A.Md\",\"pangkat\":\"Penata Muda, III/a\",\"nip\":\"199908212019031010\",\"jabatan\":\"STAFF\",\"jabatan_sk\":\"Administrator Keuangan\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk pelaksanaan proses kerja pengelolaan keuangan yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Administrator Keuangan pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa sebagaimana dimaksud pada point a perlu ditetapkan dalam keputusan Kepala Dinas Pekerjaan Umum dan Penataan Ruang.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang penyelenggaraan Negara yang bersih dan bebas dari korupsi dan nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Nomor 3851);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 27, Tambahan Lembaran Negara Nomor 4270);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negar