(73, '2023', '76.01', '1.03.0.00.0.00.01.0000', '11 TAHUN 2023', '2023-01-11', 'pengangkatan sopir kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2023', '198006152006041018', 'kepala', 'Pembina Tingkat I, IV/b', 'Sumarlin, ST, M.AP', '{\"0\":{\"nama\":\"M. IRWAN\",\"pangkat\":\"Non ASN\",\"nip\":\"Non ASN\",\"jabatan\":\"Honorer\",\"jabatan_sk\":\"Sopir Dinas Pekerjaan Umum dan Penataan Ruang Kab. Pasangkayu\"}}', 0, '{\"0\":{\"isi\":\"bahwa untuk kelancaran pelaksanaan perkantoran yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat sopir pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\"},\"1\":{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\"},\"2\":{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\"}}', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\"},\"5\":{\"isi\":\"Unda