(108, '2024', '76.01', '1.03.0.00.0.00.01.0000', '17 TAHUN 2024', '2024-01-08', 'pengangkatan pejabat pembantu pengurus barang pengguna dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2024', '198006152006041018', 'kepala', 'Pembina tingkat I, IV/b', 'Sumarlin, ST.M.AP', '[{\"nama\":\"Achmad\",\"pangkat\":\"Pengatur , II\\/c\",\"nip\":\"198105102014091001\",\"jabatan\":\"Pengadministrasi Kepegawaian\",\"jabatan_sk\":\"Pembantu Pengurus Barang Pengguna\"},{\"nama\":\"HERMAN HADDANG\",\"pangkat\":\"Penata muda, III\\/a\",\"nip\":\"198301022007011006\",\"jabatan\":\"Pengadministrasi Perencanaan dan Program\",\"jabatan_sk\":\"Pembantu Pengurus Barang Pengguna\"}]', 1, '[{\"isi\":\"bahwa untuk pelaksanaan proses kerja pengelolaan asset dan barang, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Paasangkayu, maka dipandang perlu mengangkat pembantu pengurus Barang pengguna pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2024;\",\"p_l\":\"L\"},{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"}]', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang\\/Jasa Pemerintah;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2023 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2023 tanggal 29 Desember 2023 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 27 Tahun 2023 tanggal 29 Desember 2023 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2024;\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"membantu menyiapkan dokumen rencana kebutuhan dan penganggaran barang milik daerah;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"menyiapkan usulan permohonan penetapan status penggunaan barang milik daerah yang diperoleh dari beban APBD dan perolehan lainnya yang sah;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"melaksanakan pencatatan dan inventarisasi barang milik daerah;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"membantu mengamankan barang milik daerah yang berada pada Pengguna Barang;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"menyiapkan dokumen pengajuan usulan pemanfaatan dan pemindahtanganan barang milik daerah berupa tanah dan\\/atau bangunan yang tidak memerlukan persetujuan DPRD dan barang milik daerah selain tanah dan\\/atau bangunan;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"menyiapkan dokumen penyerahan barang milik daerah berupa tanah dan\\/atau bangunan yang tidak digunakan untuk kepentingan penyelenggaraan tugas dan fungsi Pengguna Barang dan sedang tidak dimanfaatkan pihak lain;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"menyiapkan dokumen pengajuan usulan pemusnahan dan penghapusan barang milik daerah;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"menyusun laporan barang semesteran dan tahunan;\",\"p_l\":\"L\"},\"9\":{\"isi\":\"menyiapkan Surat Permintaan Barang (SPB) berdasarkan nota permintaan barang;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"mengajukan Surat Permintaan Barang (SPB) kepada Pejabat Penatausahaan Barang Pengguna;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"menyerahkan barang berdasarkan Surat Perintah Penyaluran Barang (SPPB) yang dituangkan dalam berita acara penyerahan barang;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"membuat Kartu Inventaris Ruangan (KIR) semesteran dan tahunan;\",\"p_l\":\"L\"},\"13\":{\"isi\":\"memberi label barang milik daerah;\",\"p_l\":\"L\"},\"14\":{\"isi\":\"mengajukan permohonan persetujuan kepada Pejabat Penatausahaan Pengguna Barang atas perubahan kondisi fisik barang milik daerah berdasarkan pengecekan fisik barang;\",\"p_l\":\"L\"},\"15\":{\"isi\":\"melakukan stock opname barang persediaan;\",\"p_l\":\"L\"},\"16\":{\"isi\":\"menyimpan dokumen, antara lain: fotokopi\\/salinan dokumen kepemilikan barang milik daerah dan menyimpan asli\\/fotokopi\\/salinan dokumen penatausahaan;\",\"p_l\":\"L\"},\"17\":{\"isi\":\"melakukan rekonsiliasi dalam rangka penyusunan laporan barang Pengguna Barang dan laporan barang milik daerah;\",\"p_l\":\"L\"},\"18\":{\"isi\":\"membuat laporan mutasi barang setiap bulan yang disampaikan kepada Pengelola Barang melalui Pengguna Barang setelah diteliti oleh Pejabat Penatausahaan Pengguna Barang.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2024.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Masing-masing yang bersangkutan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Pertinggal\",\"p_l\":\"L\"}}', NULL, '', '2024-04-01 07:42:33', 'nabiila', '2024-04-08 18:20:26', 'nabiila', 0, 0),
(109, '2024', '76.01', '1.03.0.00.0.00.01.0000', '42 TAHUN 2024', '2024-06-03', 'perubahan pengangkatan pejabat pelaksana teknis kegiatan (PPTK) dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2024', '198006152006041018', 'kepala', 'Pembina tingkat I, IV/b', 'Sumarlin, ST.M.AP', '[{\"nama\":\"Mahmud, SP., M.Si\",\"pangkat\":\"Pembina Tingkat I, IV\\/b\",\"nip\":\"196901272002121004\",\"jabatan\":\"Sekretaris Dinas\",\"jabatan_sk\":\"PPTK Sekretaris, UPTD Pengelolaan Air Bersih, UPTD Pengelolaan Limbah Domestik, Kegiatan Peralatan Alat Besar Dan Alat Laboratorium\"},{\"nama\":\"Kamaruddin, ST\",\"pangkat\":\"Pembina , IV\\/a\",\"nip\":\"197308142005021003\",\"jabatan\":\"Kepala Bidang Pembinaan Jasa Konstruksi\",\"jabatan_sk\":\"PPTK Bidang Pembinaan Jasa Konstruksi Dan Penataan Dan Pemanfaatan Ruang\"},{\"nama\":\"SYAMSUNAR, SP.,M.M\",\"pangkat\":\"Penata tingkat I, III\\/d\",\"nip\":\"197503102009031001\",\"jabatan\":\"Kepala bidang bina marga\",\"jabatan_sk\":\"PPTK Bidang Binamarga\"},{\"nama\":\"Nardin, ST\",\"pangkat\":\"Penata Tingkat I, III\\/d\",\"nip\":\"197910012011011004\",\"jabatan\":\"Kepala Bidang Cipta Karya\",\"jabatan_sk\":\"PPTK Bidang Cipta Karya\"},{\"nama\":\"I Nyoman Sumerta, S.T., M.P.W.P\",\"pangkat\":\"Penata Tingkat I, III\\/d\",\"nip\":\"198301012010011020\",\"jabatan\":\"Kepala Bidang Sumber Daya Air\",\"jabatan_sk\":\"PPTK Bidang Sumber Daya Air\"}]', 1, '[{\"isi\":\"bahwa untuk pelaksanaan proses kerja Pengadaan Barang \\/ Jasa Pemerintah dan kelancaran sub kegiatan yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pejabat Pelaksana Teknis Kegiatan (PPTK) pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2024;\",\"p_l\":\"L\"},{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"}]', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang\\/Jasa Pemerintah;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Pemerintah Nomor 12 Tahun 2019 tentang Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2023 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2023 tanggal 29 Desember 2023 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"13\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 27 Tahun 2023 tanggal 29 Desember 2023 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"14\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2021 tanggal 30 Desember 2021 tentang Kedudukan, Susunan Organisasi, Tugas dan Fungsi serta Tata Kerja Perangkat Daerah.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas PPTK dalam membantu tugas dan wewenang PA\\/ KPA sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"mengendalikan dan melaporkan perkembangan pelaksanaan teknis Kegiatan\\/sub kegiatan SKPD\\/Unit SKPD;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"menyiapkan dokumen dalam rangka pelaksanaan anggaran atas Beban pengeluaran pelaksanaan Kegiatan\\/Sub kegiatan;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"menyiapkan dokumen pengadaan barang\\/jasa pada Kegiatan\\/Sub kegiatan SKPD\\/Unit SKPD sesuai ketentuan peraturan perundang-undangan yang mengatur mengenai pengadaan barang\\/jasa.\",\"p_l\":\"L\"},\"4\":{\"isi\":\"PPTK untuk melaksanakan tugas PPK sebagaimana dimaksud pada ayat (1) huruf a sampai dengan huruf m Peraturan presiden Republik indonesia Nomor 12 Tahun 2021 dan perubahannnya tentang perubahan atas peraturan presiden nomor 16 Tahun 2018 tentang pengadaan barang\\/jasa pemerintah:\",\"p_l\":\"P\"},\"5\":{\"isi\":\"menyusun perencanaan pengadaan;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"melaksanakan Konsolidasi Pengadaan Barang\\/Jasa;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"menetapkan spesifikasi teknis\\/Kerangka Acuan Kerja (KAK);\",\"p_l\":\"L\"},\"8\":{\"isi\":\"menetapkan rancangan kontrak;\",\"p_l\":\"L\"},\"9\":{\"isi\":\"menetapkan HPS;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"menetapkan besaran uang muka akan dibayarkan kepada Penyedia;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"mengusulkan perubahan jadwal kegiatan;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"melaksanakan E-purchasing untuk nilai paling sedikit di atas Rp200.000.000,00 (dua ratus juta rupiah);\",\"p_l\":\"L\"},\"13\":{\"isi\":\"mengendalikan Kontrak;\",\"p_l\":\"L\"},\"14\":{\"isi\":\"menyimpan dan menjaga keutuhan seluruh dokutmen pelaksanaan kegiatan;\",\"p_l\":\"L\"},\"15\":{\"isi\":\"melaporkan pelaksanaan dan kegiatan kepada PA\\/ KPA;\",\"p_l\":\"L\"},\"16\":{\"isi\":\"menyerahkan hasil pekerjaan pelaksanaan kegiatan kepada PA\\/KPA dengan berita acara penyerahan;\",\"p_l\":\"L\"},\"17\":{\"isi\":\"menilai kinerja Penyedia;\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2024.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"dengan berlakunya surat keputusan ini, maka surat keputusan nomor 04 TAHUN 2024 tanggal 8 Januari 2024 dicabut dan dinyatakan tidak berlaku lagi;\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"L\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Masing-masing yang bersangkutan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Pertinggal\",\"p_l\":\"L\"}}', '', '', '0000-00-00 00:00:00', '', '2024-09-26 16:55:02', 'nabiila', 0, 0);
INSERT INTO `sk_asn_neo` (`id`, `tahun`, `kd_wilayah`, `kd_opd`, `nomor`, `tgl_surat_dibuat`, `tentang`, `pemberi_tgs`, `jbt_pemberi_tgs`, `pangkat_pemberi_tgs`, `nama_pemberi_tgs`, `nama_ditugaskan`, `bentuk_lampiran`, `menimbang`, `mengingat`, `menetapkan_1`, `menetapkan_2`, `menetapkan_3`, `menetapkan_4`, `tembusan`, `file`, `keterangan`, `tgl_insert`, `username_insert`, `tgl_update`, `username_update`, `disable`, `is_deleted`) VALUES
