(119, '2025', '76.01', '1.03.0.00.0.00.01.0000', '12 TAHUN 2025', '2025-01-06', 'pengangkatan administrasi kontrak dan data dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2025', '198006152006041018', 'kepala', 'Pembina tingkat I, IV/b', 'Sumarlin, ST.M.AP', '[{\"nama\":\"Sri Suhartina, S.Ap\",\"pangkat\":\"-\",\"nip\":\"Non ASN\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"administrasi kontrak dan data\"},{\"nama\":\"Nurafni Rusdin, SE\",\"pangkat\":\"-\",\"nip\":\"Non ASN\",\"jabatan\":\"honorer\",\"jabatan_sk\":\"administrasi kontrak dan data\"}]', 0, '[{\"isi\":\"bahwa untuk kelancaran pelaksanaan administrasi kontrak dan data perkantoran yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat Pengantar Surat pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\",\"p_l\":\"L\"},{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"}]', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 33 Tahun 2004 tentang Perimbangan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 126, Tambahan Lembaran Negara Republik Indonesia Nomor 4438);\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang\\/Jasa Pemerintah;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2024 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2025;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2024 tanggal 31 Desember 2024 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2025;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 39 Tahun 2024 tanggal 31 Desember 2024 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2025;\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud pada diktum Penetapan adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Mencatat, memeriksa dan memastikan kontraktual dan swakelola OPD;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Melakukan Entri Data Kontrak dan realisasi anggaran OPD;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Melaporkan hasil pelaksanaan tugas secara tertulis dan lisan kepada atasan sesuai prosedur yang berlaku;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulis maupun lisan.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2025.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Masing-masing yang bersangkutan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Pertinggal\",\"p_l\":\"L\"}}', '', '', '0000-00-00 00:00:00', '', '2025-10-22 14:17:29', 'nabiila', 0, 0),
