(126, '2025', '76.01', '1.03.0.00.0.00.01.0000', '110 TAHUN 2025', '2025-11-03', 'perubahan pengangkatan sopir kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2025', '197503102009031001', 'kepala', 'Pembina, IV/a', 'SYAMSUNAR, SP.,M.M', '[{\"nama\":\"Sugisma Wijaya\",\"pangkat\":\"Non ASN\",\"nip\":\"Non ASN\",\"jabatan\":\"Honorer\",\"jabatan_sk\":\"Sopir Dinas Pekerjaan Umum dan Penataan Ruang Kab. Pasangkayu\"}]', 0, '[{\"isi\":\"bahwa untuk kelancaran pelaksanaan perkantoran yang baik pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat sopir pada Dinas Pekerjaan Umum Kabupaten Pasangkayu;\",\"p_l\":\"L\"},{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"}]', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2024 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2024 tanggal 31 Desember 2024 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 39 Tahun 2024 tanggal 31 Desember 2024 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud penetapan adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"Memeriksa kelengkapan kendaraan;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Mengantarkan pimpinan dalam melaksanakan tugas sesuai dengan perintah;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Membersihkan Mobil\\/kendaraan dinas;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Melakukan service dan penggantian suku cadang yang sudah rusak dibengkel;\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2025.\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Dengan berlakunya Surat Keputusan ini maka Surat Keputusan Nomor 11 Tahun 2025 tentang pengangkatan sopir kantor dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2025 dicabut dan tidak berlaku lagi.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Masing-masing yang bersangkutan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Pertinggal\",\"p_l\":\"L\"}}', '', '', '0000-00-00 00:00:00', '', '2025-11-14 09:28:58', 'nabiila', 0, 0),
(127, '2025', '76.01', '1.03.0.00.0.00.01.0000', '018 TAHUN 2025', '2025-01-06', 'pengangkatan pembantu tim teknis bidang cipta karya dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2025', '198006152006041018', 'kepala', 'Pembina tingkat I, IV/b', 'Sumarlin, ST.M.AP', '[{\"nama\":\"I KETUT SURIANA,ST.,M.AP\",\"pangkat\":\"Penata Tk.I,III\\/d<br>\",\"nip\":\"198404262011011011\",\"jabatan\":\"Teknik Penyehatan Lingkungan Ahli Muda\",\"jabatan_sk\":\"Sub Kegiatan Air Minum\"},{\"nama\":\"SAFARUDDIN BAKRY,S.A.P\",\"pangkat\":\"Penata Muda, III\\/a<br>\",\"nip\":\"198012142011011005\",\"jabatan\":\"Pengamat Operasi dan Pemeliharaan Sumber Daya Air\",\"jabatan_sk\":\"Sub Kegiatan Air Minum\"},{\"nama\":\"Rahmania, ST.MT\",\"pangkat\":\"Penata tingkat I, III\\/d\",\"nip\":\"198406172009032002\",\"jabatan\":\"Teknik Penyehatan Lingkungan Ahli Muda\",\"jabatan_sk\":\"Sub Kegiatan Sanitasi\"},{\"nama\":\"Andi Jamil Zainal, ST\",\"pangkat\":\"Penata, III\\/c<br>\",\"nip\":\"197504022014091001\",\"jabatan\":\"Penelaah Teknis Kebijakan\",\"jabatan_sk\":\"Sub Kegiatan Penataan Bangunan\"},{\"nama\":\"HERTASMING,SE.,M.P.W.P\",\"pangkat\":\"Penata, III\\/c<br>\",\"nip\":\"197106222014091001\",\"jabatan\":\"Penata Layanan Operasional\",\"jabatan_sk\":\"Sub Kegiatan Penataan Bangunan\"}]', 1, '[{\"isi\":\"bahwa untuk pelaksanaan proses kerja Pengadaan Barang \\/ Jasa Pemerintah dan kelancaran sub kegiatan yang efektif, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Pasangkayu, maka dipandang perlu mengangkat pembantu tim teknis bidang cipta karya pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2025;\",\"p_l\":\"L\"},{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"},{\"isi\":\"\",\"p_l\":\"P\"}]', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2022 tentang Hubungan Keuangan Antara Pemerintah Pusat dan Pemerintah Daerah;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang\\/Jasa Pemerintah;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Pemerintah Nomor 12 Tahun 2019 tentang Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2023 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2024;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2024 tanggal 31 Desember 2024 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"13\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 39 Tahun 2024 tanggal 31 Desember 2024 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"14\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 33 Tahun 2021 tanggal 30 Desember 2021 tentang Kedudukan, Susunan Organisasi, Tugas dan Fungsi serta Tata Kerja Perangkat Daerah.<br>\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas pembantu tim teknis dalam membantu tugas dan wewenang PA\\/ KPA sebagaimana dimaksud pada diktum Kesatu adalah :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"membantu tim teknis\\/pptk (pejabat pelaksana teknis kegiatan) dalam melaksanakan tugasnya;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"membantu PPK (pejabat pembuat komitmen) dalam melaksanakan tugasnya;<br>\",\"p_l\":\"L\"},\"3\":{\"isi\":\"membantu menyiapkan dokumen pengadaan barang\\/jasa pada Kegiatan\\/Sub kegiatan SKPD\\/Unit SKPD sesuai ketentuan peraturan perundang-undangan yang mengatur mengenai pengadaan barang\\/jasa;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"membantu tugas sesuai kegiatan\\/sub kegiatan PPK dan PPTK;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"membantu&nbsp;menyusun jadwal pelaksanaan Kegiatan\\/Sub kegiatan;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"<div><span style=\\\"text-align: inherit; font-size: 1em;\\\">membantu<\\/span><span style=\\\"text-align: inherit; font-size: 1em;\\\">&nbsp;<\\/span>memonitoring dan evaluasi pelaksanaan Kegiatan\\/Sub kegiatan;<\\/div>\",\"p_l\":\"L\"},\"7\":{\"isi\":\"<div><span style=\\\"text-align: inherit; font-size: 1em;\\\">membantu<\\/span><span style=\\\"text-align: inherit; font-size: 1em;\\\">&nbsp;<\\/span>melaporkan perkembangan pelaksanaan Kegiatan\\/Sub kegiatan&nbsp;<span style=\\\"text-align: inherit; font-size: 1em;\\\">kepada PA\\/KPA;<\\/span><\\/div>\",\"p_l\":\"L\"},\"8\":{\"isi\":\"<span style=\\\"font-size: 1em; text-align: inherit;\\\">membantu<\\/span><span style=\\\"font-size: 1em; text-align: inherit;\\\">&nbsp;<\\/span>menyiapkan laporan kinerja pelaksanaan Kegiatan\\/Sub kegiatan;\",\"p_l\":\"L\"},\"9\":{\"isi\":\"membantu serah terima pekerjaan sesuai sub kegiatan.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2025.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Masing-masing yang bersangkutan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Pertinggal\",\"p_l\":\"L\"}}', '', '', '0000-00-00 00:00:00', '', '2025-11-17 05:39:46', 'nabiila', 0, 0),
(128, '2025', '76.01', '1.03.0.00.0.00.01.0000', '17 TAHUN 2025', '2025-01-06', 'pengangkatan pejabat pembantu pengurus barang pengguna dinas pekerjaan umum dan penataan ruang kabupaten pasangkayu tahun 2025', '198006152006041018', 'kepala', 'Pembina tingkat I, IV/b', 'Sumarlin, ST.M.AP', '[{\"nama\":\"Felix Datuan, ST<br>\",\"pangkat\":\"Penata tingkat I, III\\/d<br>\",\"nip\":\"198407252009031001<br>\",\"jabatan\":\"Kasubag keuangan<br>\",\"jabatan_sk\":\"Pembantu Pengurus Barang Pengguna\"},{\"nama\":\"Hertasming, SE<br>\",\"pangkat\":\"Penata, III\\/c<br>\",\"nip\":\"197106222014091001<br>\",\"jabatan\":\"Penata Layanan Operasional\",\"jabatan_sk\":\"Pembantu Pengurus Barang Pengguna\"},{\"nama\":\"Achmad<br>\",\"pangkat\":\"Pengatur , II\\/c<br>\",\"nip\":\"198105102014091001<br>\",\"jabatan\":\"Pengadministrasi Perkantoran<br>\",\"jabatan_sk\":\"Pembantu Pengurus Barang Pengguna\"}]', 1, '[{\"isi\":\"bahwa untuk pelaksanaan proses kerja pengelolaan asset dan barang, efisien dan akuntabel pada Dinas Pekerjaan Umum dan Penataan Ruang Pemerintah Daerah Kabupaten Paasangkayu, maka dipandang perlu mengangkat pembantu pengurus Barang pengguna pada Dinas Pekerjaan Umum Kabupaten Pasangkayu Tahun 2024;\",\"p_l\":\"L\"},{\"isi\":\"bahwa yang tersebut namanya dalam lampiran keputusan ini dipandang cakap dan mampu melaksanakan tugas;\",\"p_l\":\"L\"},{\"isi\":\"bahwa pengangkatan sebagaimana dimaksud pada point a perlu ditetapkan dalam Keputusan Kepala Dinas.\",\"p_l\":\"L\"}]', '{\"0\":{\"isi\":\"Undang-Undang Nomor 28 Tahun 1999 tentang Penyelenggaraan Pemerintahan yang bersih dan bebas Korupsi, Kolusi dan Nepotisme (Lembaran Negara Republik Indonesia Tahun 1999 Nomor 75, Tambahan Lembaran Negara Republik Indonesia Nomor 3581);\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Undang-Undang Nomor 28 tahun 2000 tentang usaha dan peran masyarakat Jasa Konstruksi (Lembaran Negara Republik Indonesia tahun 2000 Nomor 63);\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Undang-Undang Nomor 7 Tahun 2003 tentang Pembentukan Kabupaten Luwu Timur dan Kabupaten Mamuju Utara di Provinsi Sulawesi Selatan (Lembaran Negara Tahun 2003 Nomor 27, Tambahan Lembaran NegaraNomor 4270);\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Undang-Undang Nomor 17 Tahun 2003 tentang Keuangan Negara (Lembaran Negara Republik Indonesia Tahun 2003 Nomor 47, Tambahan Lembaran Negara Republik Indonesia Nomor 4286);\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Undang-Undang Nomor 1 Tahun 2004 tentang Perbendaharaan Negara (Lembaran Negara Republik Indonesia Tahun 2004 Nomor 5, Tambahan Lembaran Negara Republik Indonesia Nomor 4355);\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Undang-Undang Nomor 2 Tahun 2017 tentang Jasa Konstruksi;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"Peraturan Presiden Republik Indonesia Nomor 16 Tahun 2019 tentang Pengadaan Barang\\/Jasa Pemerintah;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"Peraturan Pemerintah Nomor 61 Tahun 2017 tentang Perubahan Nama Kabupaten Mamuju Utara menjadi Kabupaten Pasangkayu di Provinsi Sulawesi Barat (Lembaran Negara Republik Indonesia Tahun 2017 Nomor 312, Tambahan Lembaran Negara Republik Indonesia Nomor 6715);\",\"p_l\":\"L\"},\"8\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 77 Tahun 2020 tentang Pedoman Teknis Pengelolaan Keuangan Daerah;\",\"p_l\":\"L\"},\"9\":{\"isi\":\"Peraturan Menteri Dalam Negeri Nomor 15 Tahun 2024 tentang Pedoman Penyusunan Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"10\":{\"isi\":\"Peraturan Daerah Kabupaten Mamuju Utara Nomor 5 Tahun 2006 tentang pokok-pokok Pengelolaan Keuangan Daerah (Lembaran Daerah Nomor 5 Tahun 2006, Tambahan Lembaran Daerah Nomor 5);\",\"p_l\":\"L\"},\"11\":{\"isi\":\"Peraturan Daerah Kabupaten Pasangkayu Nomor 5 Tahun 2024 tanggal 31 Desember 2024 tentang Anggaran pendapatan dan Belanja Daerah Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"},\"12\":{\"isi\":\"Peraturan Bupati Kabupaten Pasangkayu Nomor 39 Tahun 2024 tanggal 31 Desember 2024 tentang Penjabaran Anggaran Pendapatan dan Belanja Daerah Kebupaten Pasangkayu Tahun Anggaran 2025;<br>\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Tugas Personil sebagaimana dimaksud pada diktum Kesatu adalah sebagai berikut :\",\"p_l\":\"P\"},\"1\":{\"isi\":\"membantu menyiapkan dokumen rencana kebutuhan dan penganggaran barang milik daerah;\",\"p_l\":\"L\"},\"2\":{\"isi\":\"menyiapkan usulan permohonan penetapan status penggunaan barang milik daerah yang diperoleh dari beban APBD dan perolehan lainnya yang sah;\",\"p_l\":\"L\"},\"3\":{\"isi\":\"melaksanakan pencatatan dan inventarisasi barang milik daerah;\",\"p_l\":\"L\"},\"4\":{\"isi\":\"membantu mengamankan barang milik daerah yang berada pada Pengguna Barang;\",\"p_l\":\"L\"},\"5\":{\"isi\":\"menyiapkan dokumen pengajuan usulan pemanfaatan dan pemindahtanganan barang milik daerah berupa tanah dan\\/atau bangunan yang tidak memerlukan persetujuan DPRD dan barang milik daerah selain tanah dan\\/atau bangunan;\",\"p_l\":\"L\"},\"6\":{\"isi\":\"menyiapkan dokumen penyerahan barang milik daerah berupa tanah dan\\/atau bangunan yang tidak digunakan untuk kepentingan penyelenggaraan tugas dan fungsi Pengguna Barang dan sedang tidak dimanfaatkan pihak lain;\",\"p_l\":\"L\"},\"7\":{\"isi\":\"menyiapkan dokumen pengajuan usulan pemusnahan dan penghapusan barang milik daerah;\",\"p_l\":\"L\"},\"8\":{\"isi\":\"menyusun laporan barang semesteran dan tahunan;\",\"p_l\":\"L\"},\"9\":{\"isi\":\"menyiapkan Surat Permintaan Barang (SPB) berdasarkan nota permintaan barang;\",\"p_l\":\"L\"},\"10\":{\"isi\":\"mengajukan Surat Permintaan Barang (SPB) kepada Pejabat Penatausahaan Barang Pengguna;\",\"p_l\":\"L\"},\"11\":{\"isi\":\"menyerahkan barang berdasarkan Surat Perintah Penyaluran Barang (SPPB) yang dituangkan dalam berita acara penyerahan barang;\",\"p_l\":\"L\"},\"12\":{\"isi\":\"membuat Kartu Inventaris Ruangan (KIR) semesteran dan tahunan;\",\"p_l\":\"L\"},\"13\":{\"isi\":\"memberi label barang milik daerah;\",\"p_l\":\"L\"},\"14\":{\"isi\":\"mengajukan permohonan persetujuan kepada Pejabat Penatausahaan Pengguna Barang atas perubahan kondisi fisik barang milik daerah berdasarkan pengecekan fisik barang;\",\"p_l\":\"L\"},\"15\":{\"isi\":\"melakukan stock opname barang persediaan;\",\"p_l\":\"L\"},\"16\":{\"isi\":\"menyimpan dokumen, antara lain: fotokopi\\/salinan dokumen kepemilikan barang milik daerah dan menyimpan asli\\/fotokopi\\/salinan dokumen penatausahaan;\",\"p_l\":\"L\"},\"17\":{\"isi\":\"melakukan rekonsiliasi dalam rangka penyusunan laporan barang Pengguna Barang dan laporan barang milik daerah;\",\"p_l\":\"L\"},\"18\":{\"isi\":\"membuat laporan mutasi barang setiap bulan yang disampaikan kepada Pengelola Barang melalui Pengguna Barang setelah diteliti oleh Pejabat Penatausahaan Pengguna Barang.\",\"p_l\":\"L\"}}', '{\"0\":{\"isi\":\"Segala biaya yang timbul akibat keputusan ini dibebankan kepada Pos Anggaran Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Pasangkayu Tahun Anggaran 2025.\",\"p_l\":\"P\"}}', '{\"0\":{\"isi\":\"Keputusan ini mulai berlaku pada tanggal ditetapkan dan apabila terdapat kekeliruan didalamnya akan diperbaharui sebagaimana mestinya.\",\"p_l\":\"P\"}}', '{}', '{\"0\":{\"isi\":\"Bupati Pasangkayu, di Pasangkayu\",\"p_l\":\"L\"},\"1\":{\"isi\":\"Sekretaris Daerah Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"2\":{\"isi\":\"Inspektur Inspektorat Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"3\":{\"isi\":\"Kepala Badan PKAD Kabupaten Pasangkayu di Pasangkayu\",\"p_l\":\"L\"},\"4\":{\"isi\":\"Masing-masing yang bersangkutan\",\"p_l\":\"L\"},\"5\":{\"isi\":\"Pertinggal\",\"p_l\":\"L\"}}', NULL, '', '2025-01-06 07:42:33', 'nabiila', '2025-12-04 02:30:29', 'nabiila', 0, 0),
